sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
	if (isLoading || newValue === '') {
		return;
	}

	var elecBill = parseFloat(g_form.getValue('electricity_bill'));
	var inst1 = parseFloat(g_form.getValue('installment_1'));
	var inst2 = parseFloat(g_form.getValue('installment_2'));
	var inst3 = parseFloat(g_form.getValue('installment_3'));
	var inst5 = parseFloat(g_form.getValue('installment_5'));
	var totalAmount = elecBill + inst1 + inst2 + inst3 + inst5 + parseFloat(newValue);

	g_form.setValue('total_amount_paid', totalAmount);


}
